package org.operaton.extensions.connector.aillm;

import dev.langchain4j.model.output.TokenUsage;

/**
 * Token usage summed over all model calls of one connector or delegate invocation. A count is
 * {@code null} when at least one call did not report it (some OpenAI-compatible servers omit it).
 *
 * @param inputTokens tokens sent to the model
 * @param outputTokens tokens generated by the model
 * @param totalTokens sum as reported by the provider
 * @param modelCalls number of model calls made
 */
public record LlmUsage(Long inputTokens, Long outputTokens, Long totalTokens, int modelCalls) {

    /** No call made yet. */
    public static final LlmUsage NONE = new LlmUsage(0L, 0L, 0L, 0);

    /** This usage plus one more model call. */
    public LlmUsage plus(TokenUsage usage) {
        Integer in = usage == null ? null : usage.inputTokenCount();
        Integer out = usage == null ? null : usage.outputTokenCount();
        Integer total = usage == null ? null : usage.totalTokenCount();
        return new LlmUsage(add(inputTokens, in), add(outputTokens, out), add(totalTokens, total), modelCalls + 1);
    }

    private static Long add(Long sum, Integer value) {
        return sum == null || value == null ? null : sum + value;
    }
}
